# Verifying pattern
stay_8 = []
change_8_to_2 = []
for r in range(7):
    for c in range(22):
        v = demo_input[r][c]
        out = demo_output[r][c]
        if v == 8 and out == 8:
            stay_8.append((r, c))
        elif v == 8 and out == 2:
            change_8_to_2.append((r, c))

uniform_rows = {6}
uniform_cols = {0, 5, 12, 13, 18}

both_non_uniform = all(r not in uniform_rows and c not in uniform_cols for r, c in stay_8)
print(f"8s stay 8 when non-uniform: {both_non_uniform}")

all_row_or_col_smooth = all(r in uniform_rows or c in uniform_cols for r, c in change_8_to_2)
print(f"8s become 2 only in uniform rows/cols: {all_row_or_col_smooth}")

# Check 6s that change to 2
